// Проверка входящего запроса от виджета: формат sessionId, длина сообщения.
const body = $input.first().json.body ?? {};
const message = String(body.message ?? '').replace(/\s+/g, ' ').trim();
const sessionId = String(body.sessionId ?? '');
const errors = [];

if (!/^[a-zA-Z0-9-]{8,64}$/.test(sessionId)) errors.push('Некорректный sessionId');
if (!message) errors.push('Пустое сообщение');
if (message.length > 1000) errors.push('Сообщение длиннее 1000 символов');

return [{
  json: {
    valid: errors.length === 0,
    error: errors.join('; '),
    sessionId,
    chatInput: message.slice(0, 1000),
    page: String(body.page ?? '/').slice(0, 200),
  },
}];

// Приводит ответ агента к контракту виджета {reply, sessionId}.
const raw = String($input.first().json.output ?? '').trim();
// Виджет показывает простой текст: убираем Markdown-разметку, если модель её добавила.
const reply = raw
  .replace(/\*\*(.+?)\*\*/g, '$1')
  .replace(/^#+\s*/gm, '')
  .replace(/^\s*[-*]\s+/gm, '— ');

return [{
  json: {
    reply: reply || 'Извините, не удалось сформировать ответ. Оставьте, пожалуйста, телефон — менеджер свяжется с вами.',
    sessionId: $('Проверка запроса').first().json.sessionId,
  },
}];

// Срабатывает, если LLM недоступна (лимит бесплатного тарифа, сеть, таймаут).
// Посетитель получает осмысленный ответ, а не ошибку 500.
const err = $input.first().json.error ?? {};
const text = String(err.message ?? err) + " " + String(err.description ?? "");
const isRateLimit = /\b429\b|quota|rate.?limit|resource.?exhausted|too many requests/i.test(text);

return [{
  json: {
    reply: isRateLimit
      ? 'Сейчас консультант получает много вопросов. Повторите, пожалуйста, через минуту или позвоните нам: +7 (800) 000-00-00.'
      : 'Консультант временно недоступен. Позвоните нам: +7 (800) 000-00-00 (пн–пт 9:00–19:00, сб 10:00–16:00).',
    sessionId: $('Проверка запроса').first().json.sessionId,
    degraded: true,
  },
}];
